package com.simon.offlinebms;
import java.nio.file.*;
import java.util.*;
public final class FeatureTests {
    static int checks;
    static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);checks++;}
    static void close(double a,double b,String name){check(Math.abs(a-b)<.00001,name+": "+a+" vs "+b);}
    interface Work{void run()throws Exception;}
    static void rejects(Work w,String name)throws Exception{boolean rejected=false;try{w.run();}catch(IllegalArgumentException e){rejected=true;}check(rejected,name);}
    static byte[] hex(String s){s=s.trim();byte[] b=new byte[s.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(s.substring(i*2,i*2+2),16);return b;}
    static void set(byte[] b,int n,long v,int count){for(int i=0;i<count;i++)b[n+i]=(byte)(v>>(8*i));}
    public static void main(String[] args)throws Exception{
        EnergyStats s=new EnergyStats();for(int i=0;i<=60;i++)s.add(1000000+i*60000L,50,2,"A");close(s.chargeWh,100,"Constant charge energy");close(s.chargeAh,2,"Constant charge amp hours");close(s.dischargeWh,0,"No discharge invented");check(s.observedMs==3600000,"Observed duration");close(s.peakChargeW,100,"Peak charge power");
        EnergyStats crossing=new EnergyStats();crossing.add(1000000,50,-2,"A");crossing.add(1060000,50,2,"A");close(crossing.chargeWh,100.0/240,"Charge triangle at zero crossing");close(crossing.dischargeWh,100.0/240,"Discharge triangle at zero crossing");
        EnergyStats gaps=new EnergyStats();gaps.add(1000000,50,-2,"A");gaps.add(1100000,50,-2,"A");gaps.add(1160000,50,-2,"B");close(gaps.dischargeWh,0,"Gaps and session switches excluded");check(gaps.observedMs==0,"Gap duration excluded");gaps.add(1220000,50,-2,"B");close(gaps.dischargeWh,100.0/60,"Resumes from latest valid baseline");gaps.add(1220000,50,-2,"B");close(gaps.dischargeWh,100.0/60,"Duplicate timestamp not integrated");int count=gaps.samples;gaps.add(1230000,Double.NaN,2,"B");check(gaps.samples==count,"Nonfinite reading excluded");
        close(EnergyStats.availableAh(196,280,10),168,"Reserve from capacity");close(EnergyStats.availableAh(10,280,10),0,"Below reserve");close(EnergyStats.availableAh(300,280,0),280,"Overreported remaining capacity clamped");close(EnergyStats.runtimeHours(168,-12),14,"Current runtime");check(Double.isNaN(EnergyStats.runtimeHours(168,12)),"No discharge runtime when charging");check(Double.isNaN(EnergyStats.runtimeHours(168,0)),"No infinite runtime at idle");close(EnergyStats.loadHours(10000,1000,90),9,"Inverter efficiency");check(Double.isNaN(EnergyStats.loadHours(1000,0,90)),"Zero load rejected");check(Double.isNaN(EnergyStats.loadHours(1000,100,101)),"Invalid efficiency rejected");
        AlertEngine a=new AlertEngine();AlertEngine.Config c=new AlertEngine.Config();c.enabled=true;AlertEngine.Sample low=new AlertEngine.Sample(19,0,3.1,3.3,200,30);check(a.update(c,low).isEmpty(),"First low SOC needs confirmation");check(a.update(c,low).equals(Collections.singletonList("Low state of charge")),"Second low SOC emits one alert");check(a.update(c,low).isEmpty(),"No repeat while active");a.update(c,new AlertEngine.Sample(22,0,3.1,3.3,200,30));check(a.active().size()==1,"SOC recovery hysteresis");a.update(c,new AlertEngine.Sample(24,0,3.1,3.3,200,30));check(a.active().isEmpty(),"SOC clears above recovery level");a.update(c,low);check(a.update(c,low).size()==1,"Rearms after recovery");check(a.update(c,new AlertEngine.Sample(80,1,3.1,3.3,200,30)).contains("BMS protection active"),"BMS protection immediate");c.enabled=false;a.update(c,low);check(a.active().isEmpty(),"Disabled alerts clear state");
        c.enabled=true;c.socEnabled=false;c.tempEnabled=true;c.spreadEnabled=true;c.cellsEnabled=true;AlertEngine b=new AlertEngine();AlertEngine.Sample bad=new AlertEngine.Sample(10,0,2.7,3.8,110,60);b.update(c,bad);check(b.update(c,bad).size()==4,"Temperature/spread/low/high cell thresholds");b.update(c,new AlertEngine.Sample(80,0,3.1,3.3,80,50));check(b.active().isEmpty(),"All recovered thresholds clear");AlertEngine empty=new AlertEngine();empty.update(c,new AlertEngine.Sample(80,0,Double.NaN,Double.NaN,Double.NaN,Double.NaN));check(empty.active().isEmpty(),"Missing values do not trigger alerts");
        byte[] real=hex(Files.readString(Path.of(args[0],"jk24.hex")));JkProtocol.Sample jk=JkProtocol.parse(real,"JK02_24S");check(jk.cells.length==16,"Captured JK 16-cell count");close(jk.cells[0],3.327,"Captured JK first cell");close(jk.basic.voltage,53.251,"Captured JK pack voltage");check(jk.basic.soc==84,"Captured JK SOC");close(jk.basic.capacityAh,81,"Captured JK capacity");close(jk.basic.remainingAh,68.494,"Captured JK remaining");check(JkProtocol.parse(real,"Auto").basic.vendor.equals("JK"),"Auto JK layout");
        JkProtocol.Assembler assembler=new JkProtocol.Assembler();check(assembler.feed(Arrays.copyOfRange(real,0,41)).isEmpty(),"Partial JK frame held");check(assembler.feed(Arrays.copyOfRange(real,41,300)).size()==1,"Fragmented JK frame reassembled");byte[] corrupt=real.clone();corrupt[50]^=1;assembler.reset();check(assembler.feed(corrupt).isEmpty(),"Bad JK checksum rejected");check(assembler.feed(real).size()==1,"JK resynchronizes after corruption");
        byte[] modern=new byte[300];modern[0]=0x55;modern[1]=(byte)0xaa;modern[2]=(byte)0xeb;modern[3]=(byte)0x90;modern[4]=2;for(int i=0;i<16;i++)set(modern,6+i*2,3300,2);set(modern,150,52800,4);set(modern,158,-12500,4);set(modern,162,230,2);set(modern,164,240,2);set(modern,144,250,2);modern[173]=70;set(modern,174,196000,4);set(modern,178,280000,4);set(modern,182,379,4);modern[198]=1;modern[199]=1;int sum=0;for(int i=0;i<299;i++)sum+=modern[i]&255;modern[299]=(byte)sum;JkProtocol.Sample newer=JkProtocol.parse(modern,"JK02_32S");close(newer.basic.current,-12.5,"JK32 signed discharge current");close(newer.basic.capacityAh,280,"JK32 capacity scale");close(newer.basic.temperatures[0],25,"JK32 MOS temperature offset");check(JkProtocol.parse(modern,"Auto").basic.soc==70,"JK32 auto layout");rejects(()->JkProtocol.parse(modern,"JK02_24S"),"Wrong JK layout rejected");
        check(Arrays.equals(JkProtocol.readCommand(0x96),hex("aa5590eb96000000000000000000000000000010")),"JK documented read command");boolean onlyReads=true;for(int i=0;i<256;i++)if(i!=0x96&&i!=0x97){try{JkProtocol.readCommand(i);onlyReads=false;}catch(IllegalArgumentException expected){}}check(onlyReads,"JK factory/control writes excluded");
        byte[] solar=hex(Files.readString(Path.of(args[0],"victron-solar.hex")));VictronProtocol.Data v=VictronProtocol.decode(solar,VictronProtocol.key("000102030405060708090a0b0c0d0e0f"));check(v.type==1&&v.counter==0x1234,"Victron record header");close(v.values.get("Battery voltage"),48.12,"Independent encrypted solar voltage");close(v.values.get("Battery current"),12.3,"Victron current scale");close(v.values.get("Yield today"),2.34,"Victron yield kWh");close(v.values.get("Solar power"),590,"Victron solar watts");close(v.values.get("Load current"),1.6,"Victron 9-bit field");close(v.values.get("Battery power"),48.12*12.3,"Victron derived signed power");rejects(()->VictronProtocol.decode(solar,hex("ff000000000000000000000000000000")),"Wrong key rejected by first-byte marker");rejects(()->VictronProtocol.key("1234"),"Victron PIN cannot substitute readout key");rejects(()->VictronProtocol.parse(new byte[2],1),"Truncated Victron records rejected");rejects(()->VictronProtocol.parse(new byte[16],14),"Unknown Victron record explicitly rejected");
        byte[] missing=new byte[16];Arrays.fill(missing,(byte)0xff);missing[3]=0x7f;missing[5]=0x7f;VictronProtocol.Data unknown=VictronProtocol.parse(missing,1);check(unknown.values.isEmpty(),"Unavailable Victron measurements are omitted");byte[] monitor=new byte[15];set(monitor,0,120,2);set(monitor,2,1287,2);set(monitor,6,0xffff,2);bits(monitor,64,2,3);bits(monitor,66,22,(1L<<22)-2500);bits(monitor,88,20,123);bits(monitor,108,10,750);VictronProtocol.Data bm=VictronProtocol.parse(monitor,2);close(bm.values.get("Battery current"),-2.5,"Victron signed 22-bit current");close(bm.values.get("State of charge"),75,"Victron 10-bit SOC");close(bm.values.get("Consumed capacity"),-12.3,"Victron consumed capacity sign");close(bm.values.get("Time to go"),120,"Victron minute units");System.out.println("PASS: "+checks+" offline feature, JK and Victron checks");
    }
    static void bits(byte[] data,int start,int length,long value){for(int i=0;i<length;i++)if((value&(1L<<i))!=0)data[(start+i)/8]|=1<<((start+i)%8);}
}
